28	 *       int beep(void);
29	 *       int flash(void);
30	 *
31	 * Description:
32	 *       beep() sounds the audible bell on the terminal, if possible;
33	 *       if not, it calls flash().
34	 *
35	 *       flash() "flashes" the screen, by inverting the foreground and
36	 *       background of every cell, pausing, and then restoring the
37	 *       original attributes.
38	 *
39	 * Return Value:
40	 *       These functions return OK.
41	 *
42	 * Portability                                X/Open    BSD    SYS V
43	 *       beep                                    Y       Y       Y
44	 *       flash                                   Y       Y       Y
45	 */
