57	int beep(void)
58	{
59	#ifdef CONFIG_PDCURSES_MULTITHREAD
60	  FAR struct pdc_context_s *ctx = PDC_ctx();
61	#endif
62	  PDC_LOG(("beep() - called\n"));
63	
64	  if (SP->audible)
65	    {
66	      PDC_beep();
67	    }
68	  else
69	    {
70	      flash();
71	    }
72	
73	  return OK;
74	}
75	
76	int flash(void)
77	{
78	  int x;
79	  int y;
80	  int z;
81	#ifdef CONFIG_PDCURSES_MULTITHREAD
82	  FAR struct pdc_context_s *ctx = PDC_ctx();
83	#endif
84	
85	  PDC_LOG(("flash() - called\n"));
86	
87	  /* Reverse each cell; wait; restore the screen */
88	
89	  for (z = 0; z < 2; z++)
90	    {
91	      for (y = 0; y < LINES; y++)
92	        {
93	          for (x = 0; x < COLS; x++)
94	            {
95	              curscr->_y[y][x] ^= A_REVERSE;
96	            }
97	        }
98	
99	      wrefresh(curscr);
100	
101	      if (!z)
102	        {
103	          napms(50);
104	        }
105	    }
106	
107	  return OK;
108	}
