1	/****************************************************************************
2	 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/bk7258_flash_mtd.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * BK7258 (T5-AI) on-chip flash data-partition MTD lower-half — SDK wrapper.
7	 *
8	 * Calls bk_flash_* SDK APIs.  Zero register access.
9	 * Exposes the 1 MiB data partition (logical 0x00100000..0x001FFFFF) as a
10	 * NuttX MTD.
11	 *
12	 * Geometry is fixed for the GD25Q64-class part:
13	 *   blocksize  = 4096  (read/write block unit)
14	 *   erasesize  = 4096  (sector erase unit)
15	 *   neraseblocks = 256 (1 MiB / 4 KiB)
16	 ****************************************************************************/
17	
18	/****************************************************************************
19	 * Included Files
20	 ****************************************************************************/
21	
22	#include <nuttx/config.h>
23	
24	#include <stdint.h>
25	#include <string.h>
26	#include <errno.h>
27	#include <debug.h>
28	
29	#include <nuttx/mtd/mtd.h>
30	
31	#include "bk7258_flash_mtd.h"
32	
33	/* SDK API headers */
34	
35	#include <driver/flash.h>
36	
37	/****************************************************************************
38	 * Pre-processor Definitions
39	 ****************************************************************************/
40	
41	/* Verified data partition layout (matches docs n5-flash-filesystem.md). */
42	
43	#define BK7258_DATA_PART_BASE       0x00100000u
44	#define BK7258_DATA_PART_SIZE       0x00100000u
45	
46	#define BK7258_FLASH_BLOCK_SIZE     4096u
47	#define BK7258_FLASH_ERASE_SIZE     4096u
48	#define BK7258_FLASH_NBLOCKS        (BK7258_DATA_PART_SIZE / BK7258_FLASH_BLOCK_SIZE)
49	
50	/* Known JEDEC IDs for 8 MiB GD25Q64-class parts on this board. */
51	
52	#define BK7258_FLASH_ID_GD25Q64     0x00c86517u
53	#define BK7258_FLASH_ID_GD25Q64B    0x00c84017u
54	#define BK7258_FLASH_ID_W25Q64      0x000b4017u
55	#define BK7258_FLASH_ID_TH25Q64     0x00cd6017u
56	
57	/****************************************************************************
58	 * Private Types
59	 ****************************************************************************/
60	
61	struct bk7258_flash_mtd_s
62	{
63	  struct mtd_dev_s mtd;           /* External MTD interface */
64	};
65	
66	/****************************************************************************
67	 * Private Data
68	 ****************************************************************************/
69	
70	static struct bk7258_flash_mtd_s g_bk7258_flash_mtd;
71	
72	/****************************************************************************
73	 * MTD Methods
74	 ****************************************************************************/
75	
76	/* Read whole 4 KiB blocks.  SDK bk_flash_read_bytes handles alignment. */
77	
78	static ssize_t bk7258_flash_bread(FAR struct mtd_dev_s *dev, off_t startblock,
79	                                  size_t nblocks, FAR uint8_t *buffer)
80	{
81	  uint32_t offset = BK7258_DATA_PART_BASE +
82	                    (uint32_t)startblock * BK7258_FLASH_BLOCK_SIZE;
83	  uint32_t nbytes = (uint32_t)nblocks * BK7258_FLASH_BLOCK_SIZE;
84	
85	  (void)dev;
86	
87	  if (startblock < 0 || (size_t)startblock + nblocks > BK7258_FLASH_NBLOCKS)
88	    {
89	      return -EINVAL;
90	    }
91	
92	  if (bk_flash_read_bytes(offset, buffer, nbytes) != BK_OK)
93	    {
94	      return -EIO;
95	    }
96	
97	  return (ssize_t)nblocks;
98	}
99	
100	/* Erase whole 4 KiB sectors.  SDK handles SR0 protection internally
101	 * via bk_flash_set_protect_type. */
102	
103	static int bk7258_flash_erase(FAR struct mtd_dev_s *dev, off_t startblock,
104	                              size_t nblocks)
105	{
106	  size_t block;
107	
108	  (void)dev;
109	
110	  if (startblock < 0 || (size_t)startblock + nblocks > BK7258_FLASH_NBLOCKS)
111	    {
112	      return -EINVAL;
113	    }
114	
115	  bk_flash_set_protect_type(FLASH_PROTECT_NONE);
116	
117	  for (block = 0; block < nblocks; block++)
118	    {
119	      uint32_t addr = BK7258_DATA_PART_BASE +
120	                      ((size_t)startblock + block) * BK7258_FLASH_BLOCK_SIZE;
121	
122	      if (bk_flash_erase_sector(addr) != BK_OK)
123	        {
124	          bk_flash_set_protect_type(FLASH_UNPROTECT_LAST_BLOCK);
125	          return -EIO;
126	        }
127	    }
128	
129	  bk_flash_set_protect_type(FLASH_UNPROTECT_LAST_BLOCK);
130	  return OK;
131	}
132	
133	/* Write whole 4 KiB blocks.  SDK bk_flash_write_bytes handles 32-byte
134	 * page programming internally. */
135	
136	static ssize_t bk7258_flash_bwrite(FAR struct mtd_dev_s *dev, off_t startblock,
137	                                   size_t nblocks, FAR const uint8_t *buffer)
138	{
139	  uint32_t offset = BK7258_DATA_PART_BASE +
140	                    (uint32_t)startblock * BK7258_FLASH_BLOCK_SIZE;
141	  uint32_t nbytes = (uint32_t)nblocks * BK7258_FLASH_BLOCK_SIZE;
142	
143	  (void)dev;
144	
145	  if (startblock < 0 || (size_t)startblock + nblocks > BK7258_FLASH_NBLOCKS)
146	    {
147	      return -EINVAL;
148	    }
149	
150	  bk_flash_set_protect_type(FLASH_PROTECT_NONE);
151	
152	  if (bk_flash_write_bytes(offset, buffer, nbytes) != BK_OK)
153	    {
154	      bk_flash_set_protect_type(FLASH_UNPROTECT_LAST_BLOCK);
155	      return -EIO;
156	    }
157	
158	  bk_flash_set_protect_type(FLASH_UNPROTECT_LAST_BLOCK);
159	  return (ssize_t)nblocks;
160	}
161	
162	static int bk7258_flash_ioctl(FAR struct mtd_dev_s *dev, int cmd,
163	                              unsigned long arg)
164	{
165	  switch (cmd)
166	    {
167	      case MTDIOC_GEOMETRY:
168	        {
169	          FAR struct mtd_geometry_s *geo =
170	              (FAR struct mtd_geometry_s *)arg;
171	
172	          if (geo == NULL)
173	            {
174	              return -EINVAL;
175	            }
176	
177	          geo->blocksize    = BK7258_FLASH_BLOCK_SIZE;
178	          geo->erasesize    = BK7258_FLASH_ERASE_SIZE;
179	          geo->neraseblocks = BK7258_FLASH_NBLOCKS;
180	          strncpy(geo->model, "bk7258-data", sizeof(geo->model));
181	        }
182	        return OK;
183	
184	      case MTDIOC_ERASESTATE:
185	        {
186	          FAR uint8_t *state = (FAR uint8_t *)arg;
187	
188	          if (state == NULL)
189	            {
190	              return -EINVAL;
191	            }
192	
193	          *state = 0xff;
194	        }
195	        return OK;
196	
197	      default:
198	        break;
199	    }
200	
201	  (void)dev;
202	  return -ENOTTY;
203	}
204	
205	/****************************************************************************
206	 * Public Functions
207	 ****************************************************************************/
208	
209	FAR struct mtd_dev_s *bk7258_flash_mtd_initialize(void)
210	{
211	  uint32_t id;
212	
213	  /* Initialize the SDK flash driver (clock, protection config, etc.) */
214	
215	  if (bk_flash_driver_init() != BK_OK)
216	    {
217	      ferr("ERROR: bk_flash_driver_init failed\n");
218	      return NULL;
219	    }
220	
221	  /* Singleton: the interface struct is statically populated. */
222	
223	  g_bk7258_flash_mtd.mtd.erase  = bk7258_flash_erase;
224	  g_bk7258_flash_mtd.mtd.bread  = bk7258_flash_bread;
225	  g_bk7258_flash_mtd.mtd.bwrite = bk7258_flash_bwrite;
226	  g_bk7258_flash_mtd.mtd.read   = NULL;
227	#ifdef CONFIG_MTD_BYTE_WRITE
228	  g_bk7258_flash_mtd.mtd.write  = NULL;
229	#endif
230	  g_bk7258_flash_mtd.mtd.ioctl  = bk7258_flash_ioctl;
231	  g_bk7258_flash_mtd.mtd.isbad  = NULL;
232	  g_bk7258_flash_mtd.mtd.markbad = NULL;
233	  g_bk7258_flash_mtd.mtd.name   = "bk7258-data";
234	
235	  /* Verify JEDEC ID for known 8 MiB parts. */
236	
237	  id = bk_flash_get_id() & 0x00ffffffu;
238	
239	  if (id != BK7258_FLASH_ID_GD25Q64 &&
240	      id != BK7258_FLASH_ID_GD25Q64B &&
241	      id != BK7258_FLASH_ID_W25Q64 &&
242	      id != BK7258_FLASH_ID_TH25Q64)
243	    {
244	      ferr("ERROR: Unknown flash ID 0x%06" PRIx32 "\n", id);
245	      return NULL;
246	    }
247	
248	  return &g_bk7258_flash_mtd.mtd;
249	}
