/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

#ifdef __cplusplus
extern "C"
{
#endif

static inline volatile struct bk7258_ap_boot_state_s *
bk7258_ap_boot_state(void)
{
  return (volatile struct bk7258_ap_boot_state_s *)BK7258_SHARED_RAM_BASE;
