397	/* 1. power up uart
398	 * 2. set clock
399	 * 3. set gpio as uart
400	 */
401	static bk_err_t uart_id_init_common(uart_id_t id)
402	{
403		bk_err_t ret = 0;
404	
405	#if (CONFIG_SYSTEM_CTRL)
406		uart_clock_enable(id);
407		sys_drv_uart_select_clock(id, UART_SCLK_XTAL_26M);
408	#else
409		power_uart_pwr_up(id);
410		clk_set_uart_clk_26m(id);
411	#endif
412	
413		uart_init_gpio(id);
414		ret = uart_id_init_kfifo(id);
415		uart_statis_id_init(id);
416	
417		s_uart_sema[id].rx_blocked = false;
418		if (s_uart_sema[id].rx_int_sema == NULL) {
419			ret = rtos_init_semaphore(&(s_uart_sema[id].rx_int_sema), 1);
420			BK_ASSERT(kNoErr == ret); /* ASSERT VERIFIED */
421		}
422		s_uart[id].id_init_bits |= BIT(id);
423		s_uart[id].id_sw_fifo_enable_bits |= BIT(id);
424	
425	#if CONFIG_UART_RX_DMA
426		//default not enable rx dma
427		s_uart[id].rx_dma_enable = 0;
428	#endif
429	#if CONFIG_UART_TX_DMA
430		//default not enable tx dma
431		s_uart[id].tx_dma_enable = 0;
432	#endif
433	
434		return ret;
435	}
436	
437	static void uart_id_deinit_common(uart_id_t id)
438	{
439		s_uart[id].id_init_bits &= ~BIT(id);
440	#if CONFIG_UART_RX_DMA
441		s_uart[id].rx_dma_enable = 0;
442	#endif
443	#if CONFIG_UART_TX_DMA
444		s_uart[id].tx_dma_enable = 0;
445	#endif
446	
447		uart_hal_stop_common(&s_uart[id].hal, id);
448		uart_hal_reset_config_to_default(&s_uart[id].hal, id);
449	#if (CONFIG_SYSTEM_CTRL)
450		uart_interrupt_disable(id);
451		uart_clock_disable(id);
452	#else
453		icu_disable_uart_interrupt(id);
454		power_uart_pwr_down(id);
455	#endif
456		uart_id_deinit_kfifo(id);
457		if(s_uart_sema[id].rx_int_sema)
458		{
459			rtos_deinit_semaphore(&(s_uart_sema[id].rx_int_sema));
460			s_uart_sema[id].rx_int_sema = NULL;
461		}
462	}
