33	#define BK7258_SDK_IRQ_PRIORITY_MAX \
34	  ((1u << BK7258_SDK_IRQ_PRIORITY_BITS) - 1u)
35	
36	/****************************************************************************
37	 * Compile-time Invariants
38	 ****************************************************************************/
39	
40	_Static_assert(BK7258_SDK_IRQ_COUNT == 64,
41	               "Stage B gate: SDK IRQ source count must be 64");
42	_Static_assert(INT_SRC_NONE == BK7258_EXTERNAL_IRQS,
43	               "Stage B gate: SDK INT_SRC_NONE must follow source 63");
44	_Static_assert(BK7258_SDK_IRQ_FIRST + BK7258_SDK_IRQ_COUNT == NR_IRQS,
45	               "Stage B gate: SDK source 0..63 must map to IRQ 16..79");
46	_Static_assert(BK7258_SDK_IRQ_PRIORITY_BITS == 3,
47	               "Stage B gate: STAR NVIC implements three priority bits");
48	_Static_assert(INT_SRC_LCD == 27,
49	               "Stage B gate: LCD priority exception must remain source 27");
50	_Static_assert(BK7258_SDK_IRQ_DEFAULT_PRIORITY <=
51	               BK7258_SDK_IRQ_PRIORITY_MAX,
52	               "Stage B gate: SDK default priority must be encodable");
53	_Static_assert(BK7258_SDK_IRQ_LCD_PRIORITY <=
54	               BK7258_SDK_IRQ_PRIORITY_MAX,
55	               "Stage B gate: SDK LCD priority must be encodable");
56	
57	/****************************************************************************
58	 * Private Data
59	 ****************************************************************************/
60	
61	static spinlock_t g_bk7258_sdk_irq_lock = SP_UNLOCKED;
62	static int_group_isr_t g_bk7258_sdk_irq_handlers[BK7258_SDK_IRQ_COUNT];
63	
64	/****************************************************************************
65	 * Private Functions
66	 ****************************************************************************/
67	
68	static int bk7258_sdk_source_to_irq(icu_int_src_t source)
69	{
70	  unsigned int index = (unsigned int)source;
71	
72	  if (index >= BK7258_SDK_IRQ_COUNT)
73	    {
74	      return -1;
75	    }
76	
77	  return BK7258_SDK_IRQ_FIRST + (int)index;
78	}
79	
80	static int bk7258_sdk_irq_encode_priority(uint32_t priority)
81	{
82	  if (priority > BK7258_SDK_IRQ_PRIORITY_MAX)
83	    {
84	      return -1;
85	    }
86	
87	  return (int)(priority << BK7258_SDK_IRQ_PRIORITY_SHIFT);
88	}
89	
90	static uint32_t bk7258_sdk_irq_default_priority(icu_int_src_t source)
91	{
92	  if (source == INT_SRC_LCD)
93	    {
94	      return BK7258_SDK_IRQ_LCD_PRIORITY;
95	    }
96	
97	  return BK7258_SDK_IRQ_DEFAULT_PRIORITY;
98	}
99	
100	static int bk7258_sdk_irq_dispatch(int irq, void *context, void *arg)
101	{
102	  unsigned int source;
103	  int_group_isr_t handler;
104	
105	  (void)context;
106	  (void)arg;
107	
108	  source = (unsigned int)(irq - BK7258_SDK_IRQ_FIRST);
109	  if (source >= BK7258_SDK_IRQ_COUNT)
110	    {
111	      return OK;
112	    }
113	
114	  handler = g_bk7258_sdk_irq_handlers[source];
115	  if (handler != NULL)
116	    {
117	      handler();
118	    }
119	
120	  return OK;
121	}
122	
123	static bk_err_t
124	bk7258_sdk_irq_unregister_locked(unsigned int index, int irq)
125	{
126	  int ret;
127	
128	  up_disable_irq(irq);
129	  bk7258_clear_pending_irq(irq);
130	  g_bk7258_sdk_irq_handlers[index] = NULL;
131	  UP_DSB();
132	  UP_ISB();
133	
134	  ret = irq_detach(irq);
135	  return ret < 0 ? BK_FAIL : BK_OK;
136	}
