138	/****************************************************************************
139	 * Public Functions
140	 ****************************************************************************/
141	
142	bk_err_t bk_int_isr_register(icu_int_src_t source,
143	                             int_group_isr_t handler, void *arg)
144	{
145	  unsigned int index = (unsigned int)source;
146	  irqstate_t flags;
147	  bk_err_t result;
148	  int priority;
149	  int irq;
150	  int ret;
151	
152	  (void)arg; /* The CP CM33 SDK implementation also ignores this argument. */
153	
154	  irq = bk7258_sdk_source_to_irq(source);
155	  if (irq < 0)
156	    {
157	      return BK_ERR_INT_DEVICE_NONE;
158	    }
159	
160	  priority = bk7258_sdk_irq_encode_priority(
161	      bk7258_sdk_irq_default_priority(source));
162	  flags = spin_lock_irqsave(&g_bk7258_sdk_irq_lock);
163	
164	  /* Registration replaces the previous owner of this source.  Keep the line
165	   * disabled and non-pending until both NuttX dispatch state and priority are
166	   * complete.
167	   */
168	
169	  result = bk7258_sdk_irq_unregister_locked(index, irq);
170	  if (result != BK_OK)
171	    {
172	      goto out;
173	    }
174	
175	  ret = up_prioritize_irq(irq, priority);
176	  if (ret < 0)
177	    {
178	      result = BK_FAIL;
179	      goto out;
180	    }
181	
182	  /* A NULL SDK callback has the same net effect as the vendor CM33 path:
183	   * the previous callback is removed and the interrupt stays disabled.
184	   */
185	
186	  if (handler == NULL)
187	    {
188	      result = BK_OK;
189	      goto out;
190	    }
191	
192	  ret = irq_attach(irq, bk7258_sdk_irq_dispatch, NULL);
193	  if (ret < 0)
194	    {
195	      result = BK_FAIL;
196	      goto out;
197	    }
198	
199	  g_bk7258_sdk_irq_handlers[index] = handler;
200	  UP_DSB();
201	  UP_ISB();
202	  up_enable_irq(irq);
203	  result = BK_OK;
204	
205	out:
206	  spin_unlock_irqrestore(&g_bk7258_sdk_irq_lock, flags);
207	  return result;
208	}
209	
210	bk_err_t bk_int_isr_unregister(icu_int_src_t source)
211	{
212	  unsigned int index = (unsigned int)source;
213	  irqstate_t flags;
214	  bk_err_t result;
215	  int irq;
216	
217	  irq = bk7258_sdk_source_to_irq(source);
218	  if (irq < 0)
219	    {
220	      return BK_ERR_INT_DEVICE_NONE;
221	    }
222	
223	  flags = spin_lock_irqsave(&g_bk7258_sdk_irq_lock);
224	  result = bk7258_sdk_irq_unregister_locked(index, irq);
225	  spin_unlock_irqrestore(&g_bk7258_sdk_irq_lock, flags);
226	  return result;
227	}
228	
229	bk_err_t bk_int_set_priority(icu_int_src_t source, uint32_t priority)
230	{
231	  irqstate_t flags;
232	  bk_err_t result;
233	  int encoded;
234	  int irq;
235	
236	  irq = bk7258_sdk_source_to_irq(source);
237	  if (irq < 0)
238	    {
239	      return BK_ERR_INT_DEVICE_NONE;
240	    }
241	
242	  encoded = bk7258_sdk_irq_encode_priority(priority);
243	  if (encoded < 0)
244	    {
245	      return BK_ERR_NOT_SUPPORT;
246	    }
247	
248	  flags = spin_lock_irqsave(&g_bk7258_sdk_irq_lock);
249	  result = up_prioritize_irq(irq, encoded) < 0 ? BK_FAIL : BK_OK;
250	  spin_unlock_irqrestore(&g_bk7258_sdk_irq_lock, flags);
251	  return result;
252	}
253	
254	#ifdef CONFIG_BK7258_SDK_IRQ_TIMER_TEST
255	bk_err_t bk7258_sdk_irq_test_snapshot_handler(icu_int_src_t source,
256	                                               int_group_isr_t *handler)
257	{
258	  unsigned int index = (unsigned int)source;
259	  irqstate_t flags;
260	
261	  if (handler == NULL)
262	    {
263	      return BK_FAIL;
264	    }
265	
266	  if (bk7258_sdk_source_to_irq(source) < 0)
267	    {
268	      return BK_ERR_INT_DEVICE_NONE;
269	    }
270	
271	  flags = spin_lock_irqsave(&g_bk7258_sdk_irq_lock);
272	  *handler = g_bk7258_sdk_irq_handlers[index];
273	  spin_unlock_irqrestore(&g_bk7258_sdk_irq_lock, flags);
274	  return BK_OK;
275	}
276	#endif
