278	void interrupt_init(void)
279	{
280	  /* NuttX up_irqinitialize() already owns VTOR, g_irqvector, and the NVIC. */
281	}
282	
283	void interrupt_deinit(void)
284	{
285	  irqstate_t flags;
286	  unsigned int source;
287	
288	  flags = spin_lock_irqsave(&g_bk7258_sdk_irq_lock);
289	
290	  for (source = 0; source < BK7258_SDK_IRQ_COUNT; source++)
291	    {
292	      if (g_bk7258_sdk_irq_handlers[source] != NULL)
293	        {
294	          bk7258_sdk_irq_unregister_locked(
295	              source, BK7258_SDK_IRQ_FIRST + (int)source);
296	        }
297	    }
298	
299	  spin_unlock_irqrestore(&g_bk7258_sdk_irq_lock, flags);
300	}
