625	bk_err_t uart_write_string(uart_id_t id, const char *string)
626	{
627		const char *p = string;
628	
629		while (*string) {
630			if (*string == '\n') {
631				if (p == string || *(string - 1) != '\r')
632					uart_write_byte(id, '\r'); /* append '\r' */
633			}
634			uart_write_byte(id, *string++);
635		}
636	
637		return BK_OK;
638	}
