1972			{
1973				pm_sleep_cb_t cb_item = {dev_id, *enter_config};
1974				// use exit_config to indicate the execution priority when entering sleep
1975				if ((enter_config->cb != NULL) && (exit_config != NULL) && ((pm_cb_priority_e)exit_config->args < PM_CB_PRIORITY_MAX))
