1991		{
1992			if (enter_config != NULL)
1993			{
1994				pm_sleep_cb_t cb_item = {dev_id, *enter_config};
1995				if ((enter_config->cb != NULL) && (dev_id < PM_DEV_ID_DEFAULT))
1996				{
1997					pm_sleep_cb_push_item(s_pm_superdeep_enter_cb_conf, &s_pm_superdeep_enter_cb_cnt[PM_CB_PRIORITY_0], cb_item);
1998				}
1999				else if ((enter_config->cb != NULL) && (dev_id < PM_DEV_ID_MAX))
2000				{
2001					pm_sleep_cb_push_item(s_pm_superdeep_enter_cb_conf, &s_pm_superdeep_enter_cb_cnt[PM_CB_PRIORITY_1], cb_item);
2002				}
2003			}
2004		}
2005	#endif
2006		else
2007		{
2008			BK_LOGD(NULL,"The sleep mode[%d] not support register call back \r\n", sleep_mode);
