136	bk_err_t bk_gpio_driver_init(void)
137	{
138		//avoid re-init caused some info lost
139		if(s_gpio_is_init) {
140			GPIO_LOGD("%s:has inited \r\n", __func__);
141			return BK_OK;
142		}
143	
144		gpio_hal_init(&s_gpio.hal);
145		/*
146		 * @NOTES:
147		 * GPIO wakeup system from deepsleep(system will power off at deep sleep status),
148		 * the GPIO interrupt status is still keeped as GPIO is at AON power domain.
149		 * so bake up the specific gpio id which wakeup system, and then clear
150		 * all of the previous GPIO status before init GPIO ID relate function.
151		 */
152	#ifdef CONFIG_GPIO_WAKEUP_SUPPORT
153		gpio_record_wakeup_pin_id();
154		gpio_lowpower_keep_status_init();
155	#if CONFIG_GPIO_DYNAMIC_WAKEUP_SUPPORT
156		gpio_dynamic_wakeup_source_init();
157	#endif
158	#endif
159	
160	#if CONFIG_GPIO_DEFAULT_SET_SUPPORT
161		gpio_hal_default_map_init(&s_gpio.hal);
162	#endif
163	
164	#if (CONFIG_CPU_CNT > 1) && CONFIG_MAILBOX
165		amp_res_init(AMP_RES_ID_GPIO);
166	#endif
167	
168		//Move ISR to last to avoid other resouce doesn't finish but isr has came.
169		//F.E:GPIO wakeup deepsleep.
170	#if CONFIG_TZ && (!CONFIG_SPE)
171		bk_int_isr_register(INT_SRC_GPIO_NS, gpio_isr, NULL);
172	#else
173		bk_int_isr_register(INT_SRC_GPIO, gpio_isr, NULL);
174	#endif
175	
176		s_gpio_is_init = true;
177		return BK_OK;
178	}
