243	                }
244	            }
245	          else
246	            {
247	              pbuf = &ch;
248	              nbytes = 1;
249	
250	              ret = uart_recvbuf(dev, pbuf, nbytes);
251	              if (ret <= 0)
252	                {
253	                  continue;
254	                }
255	            }
256	        }
257	      else if(dev->ops->receive)
258	        {
259	          unsigned int status;
260	
261	          ch = uart_receive(dev, &status);
262	          pbuf = &ch;
263	          nbytes = 1;
264	
265	          /* If the RX buffer becomes full, then the serial data is
266	           * discarded. This is necessary because on most serial hardware,
267	           * you must read the data in order to clear the RX interrupt.
268	           * An option on some hardware might be to simply disable RX
269	           * interrupts until the RX buffer becomes non-FULL. However, that
270	           * would probably just cause the overrun to occur in hardware
271	           * (unless it has some large internal buffering).
272	           */
273	
274	          if (!is_full)
275	            {
276	              /* Add the character to the buffer */
277	
278	              rxbuf->buffer[rxbuf->head] = ch;
279	
280	              /* Increment the head index */
281	
282	              rxbuf->head = nexthead;
283	            }
284	        }
285	
286	#if defined(CONFIG_TTY_SIGINT) || defined(CONFIG_TTY_SIGTSTP) || \
287	    defined(CONFIG_TTY_FORCE_PANIC) || defined(CONFIG_TTY_LAUNCH)
288	      signo = uart_check_special(dev, pbuf, nbytes);
289	#endif
290	    }
291	
292	  /* If any bytes were added to the buffer, inform any waiters there is new
293	   * incoming data available.
294	   */
295	
296	  if (rxbuf->head >= rxbuf->tail)
297	    {
298	      nbytes = rxbuf->head - rxbuf->tail;
299	    }
300	  else
301	    {
302	      nbytes = rxbuf->size - rxbuf->tail + rxbuf->head;
303	    }
304	
305	#ifdef CONFIG_SERIAL_TERMIOS
306	  if (nbytes >= dev->minrecv)
307	#else
308	  if (nbytes)
309	#endif
310	    {
311	      uart_datareceived(dev);
312	    }
313	
314	#if defined(CONFIG_TTY_SIGINT) || defined(CONFIG_TTY_SIGTSTP) || \
315	    defined(CONFIG_TTY_FORCE_PANIC) || defined(CONFIG_TTY_LAUNCH)
316	  /* Send the signal if necessary */
317	
318	  if (signo != 0)
319	    {
320	      nxsig_tgkill(-1, dev->pid, signo);
321	    }
322	#endif
323	}
