274	/****************************************************************************
275	 * Name: bk7258_uart_rxavailable / receive
276	 *
277	 * 配合完成"从 SDK 收一个字节"：
278	 *   rxavailable —— 缓存空时非阻塞读 1 字节(timeout=0)，读到就缓存并返回 true
279	 *   receive    —— 把缓存的字节交给 NuttX 上层并清空
280	 * 这样 uart_recvchars 循环每次迭代恰好消费 1 字节，不会重复读。
281	 ****************************************************************************/
282	
283	static bool bk7258_uart_rxavailable(struct uart_dev_s *dev)
284	{
285	  struct bk7258_uart_s *priv = (struct bk7258_uart_s *)dev->priv;
286	  if (priv->rxbyte < 0)
287	    {
288	      uint8_t b;
289	      int n = bk_uart_read_bytes(priv->id, &b, 1,0);  /* 0 = 不阻塞 */
290	      if (n == 1)
291	        {
292	          priv->rxbyte = b;
293	        }
294	      else
295	        {
296	          priv->rxbyte = -1;
297	        }
298	    }
299	
300	  /* fifo_port is the shared RX/TX data word.  bits [0:7]  = TX byte written
301	   * by the CPU; bits [8:15] = RX byte popped on read.  Reading bit8:15
302	   * returns the next byte from the RX FIFO.
303	   */
304	
305	  return priv->rxbyte >= 0;
306	}
