310	{
311	  struct bk7258_uart_s *priv = dev->priv;
312	  int ch = priv->rxbyte;
313	
314	  priv->rxbyte = -1;   /* 消费掉缓存 */
315	  if (status)
316	    {
317	      *status = 0;
318	    }
319	
320	  return ch;
