1362	static bool _buildComposition(LottieComposition* comp, LottieLayer* parent)
1363	{
1364	    if (parent->children.count == 0) return false;
1365	    if (parent->buildDone) return true;
1366	    parent->buildDone = true;
1367	
1368	    for (auto c = parent->children.begin(); c < parent->children.end(); ++c) {
1369	        auto child = static_cast<LottieLayer*>(*c);
1370	
1371	        //attach the precomp layer.
1372	        if (child->rid) _buildReference(comp, child);
1373	
1374	        if (child->matteType != CompositeMethod::None) {
1375	            //no index of the matte layer is provided: the layer above is used as the matte source
1376	            if (child->mid == -1) {
1377	                if (c > parent->children.begin()) {
1378	                    child->matteTarget = static_cast<LottieLayer*>(*(c - 1));
1379	                }
1380	            //matte layer is specified by an index.
1381	            } else child->matteTarget = parent->layerByIdx(child->mid);
1382	        }
1383	
1384	        if (child->matteTarget) {
1385	            //parenting
1386	            _buildHierarchy(parent, child->matteTarget);
1387	            //precomp referencing
1388	            if (child->matteTarget->rid) _buildReference(comp, child->matteTarget);
1389	        }
1390	        _buildHierarchy(parent, child);
1391	
1392	        //attach the necessary font data
1393	        if (child->type == LottieLayer::Text) _attachFont(comp, child);
1394	    }
1395	    return true;
